package com.audiobookdownloader;
import android.app.*;import android.content.*;import android.content.pm.PackageInfo;import android.graphics.Color;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;
/** Version notes are independent of the audio screen and are acknowledged once they are displayed. */
public final class ReleaseNotesActivity extends Activity {
 private static int presented;
 public static void schedule(Activity activity){activity.getWindow().getDecorView().postDelayed(()->{if(activity.isDestroyed()||activity.isFinishing()||!activity.hasWindowFocus()||presented==BuildConfig.VERSION_CODE)return;try{PackageInfo p=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0);int seen=activity.getSharedPreferences("audiobook_downloader",0).getInt("release_notes_seen_code",0);if(ReleaseNotesPolicy.shouldShow(p.firstInstallTime,p.lastUpdateTime,BuildConfig.VERSION_CODE,seen)){presented=BuildConfig.VERSION_CODE;activity.startActivity(new Intent(activity,ReleaseNotesActivity.class));}}catch(Exception ignored){}},1800);}
 @Override public void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xff101725);LinearLayout root=new LinearLayout(this);root.setOrientation(1);int pad=(int)(22*getResources().getDisplayMetrics().density);root.setPadding(pad,pad*2,pad,pad*2);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(pad,pad+i.getSystemWindowInsetTop(),pad,pad+i.getSystemWindowInsetBottom());return i;});scroll.addView(root);setContentView(scroll);
  add(root,"Что нового · "+BuildConfig.VERSION_NAME,25);try(InputStream in=getAssets().open("release-notes.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1){if(out.size()+n>32768)throw new IOException();out.write(b,0,n);}JSONArray changes=new JSONObject(out.toString("UTF-8")).getJSONArray("changes");for(int k=0;k<changes.length();k++)add(root,"• "+changes.getString(k),16);}catch(Exception e){add(root,"Версия "+BuildConfig.VERSION_NAME+" установлена. Библиотека и настройки сохранены.",16);}
  Button close=new Button(this);close.setText("Понятно");root.addView(close);close.setOnClickListener(v->finish());getSharedPreferences("audiobook_downloader",0).edit().putInt("release_notes_seen_code",BuildConfig.VERSION_CODE).apply();
 }
 private void add(LinearLayout root,String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setPadding(0,12,0,20);root.addView(t);}
}
